const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
cfg.thresholds = [30, 14, 7, 1];
cfg.formUrl = cfg.n8nUrl + '/form/mdm-verlaengerung';
cfg.checklists = {
  apns: [
    'Verlaengerung des APNs-Push-Zertifikats (einmal im Jahr):',
    '1. Neue Anfrage erzeugen: scripts/mdm-apns.sh request <E-Mail> (Repo capulus-core, argocd/apps/tech/mdm/scripts).',
    '2. Signierte Anfrage aus der Mail von mdmcert.download speichern und entschluesseln: scripts/mdm-apns.sh decrypt <Anhang>.',
    '3. Auf https://identity.apple.com mit DERSELBEN Apple Account anmelden, mit der das Zertifikat erstellt wurde. Beim vorhandenen Zertifikat "Renew" waehlen (nicht "Create a Certificate"), push.req hochladen und push.pem herunterladen.',
    '4. Im Formular ' + cfg.formUrl + ' "Push-Zertifikat erneuern" waehlen und push.pem sowie push.key hochladen.',
    '5. Die Bestaetigung mit dem neuen Ablaufdatum abwarten.',
    'Achtung: Mit "Create" statt "Renew" oder einer anderen Apple Account aendert sich das Push-Topic, dann muessen alle iPads neu enrollt werden.',
    'Details: ' + 'https://github.com/pkr-lab/pkr-lab-docs/blob/main/capulus/capulus-core/3-apps-workloads/300v0-mdm-betrieb.md'
  ].join('\n'),
  dep: [
    'Verlaengerung des DEP-Tokens (einmal im Jahr):',
    '1. In Apple Business (https://business.apple.com) unter Einstellungen > MDM-Server den Capulus-MDM-Server oeffnen und "Token herunterladen" waehlen (.p7m).',
    '2. Im Formular ' + cfg.formUrl + ' "DEP-Token erneuern" waehlen und die .p7m-Datei hochladen.',
    '3. Die Bestaetigung mit dem neuen Ablaufdatum abwarten.',
    'Details: ' + 'https://github.com/pkr-lab/pkr-lab-docs/blob/main/capulus/capulus-core/3-apps-workloads/300v0-mdm-betrieb.md'
  ].join('\n'),
  scep: [
    'Die SCEP-CA laeuft ab. Danach koennen sich iPads nicht mehr per SCEP ausweisen und die MDM-Verbindung bricht ab.',
    'Eine neue CA bedeutet: neues Enrollment-Profil und Neu-Enrollment aller iPads (Zuruecksetzen und erneut registrieren). Mindestens sechs Monate vorher planen.',
    'Vorgehen: ' + 'https://github.com/pkr-lab/pkr-lab-docs/blob/main/capulus/capulus-core/3-apps-workloads/300v0-mdm-betrieb.md' + ' (Abschnitt SCEP-CA erneuern).'
  ].join('\n')
};
cfg.labels = { apns: 'APNs-Push-Zertifikat', dep: 'DEP-Token', scep: 'SCEP-CA' };
return [{ json: cfg }];

const { X509Certificate } = require('crypto');
const cfg = $('Konfiguration').first().json;
const today = Date.now();
const entry = (item, expiry, error) => {
  const label = cfg.labels[item];
  if (error) return { json: { item, label, error } };
  const days = Math.floor((new Date(expiry).getTime() - today) / 86400000);
  return { json: { item, label, expiry: new Date(expiry).toISOString().slice(0, 10), days } };
};
const out = [];
const push = $('Push-Zertifikat lesen').first().json;
if (push.cert_pem) {
  try {
    out.push(entry('apns', new X509Certificate(push.cert_pem).validTo));
  } catch (e) {
    out.push(entry('apns', null, 'Zertifikat nicht lesbar: ' + e.message));
  }
} else {
  out.push(entry('apns', null, 'Es ist noch kein Push-Zertifikat in NanoMDM hinterlegt.'));
}
const dep = $('DEP-Token lesen').first().json;
if (dep.statusCode === 200 && dep.body && dep.body.access_token_expiry) {
  out.push(entry('dep', dep.body.access_token_expiry));
} else {
  out.push(entry('dep', null, 'Es ist noch kein DEP-Token in NanoDEP hinterlegt (HTTP ' + (dep.statusCode || dep.error || 'keine Antwort') + ').'));
}
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  out.push(entry('scep', new X509Certificate(buffer).validTo));
} catch (e) {
  out.push(entry('scep', null, 'SCEP-CA nicht abrufbar: ' + e.message));
}
return out;

const cfg = $('Konfiguration').first().json;
const out = [];
for (const row of $input.all().map((item) => item.json)) {
  const info = typeof row.info === 'string' ? JSON.parse(row.info) : row.info;
  const sent = (row.sent || []).map(Number);
  const guide = cfg.checklists[info.item];
  if (info.error) {
    out.push({ json: { item: info.item, expiry: null, mark: [], ticket: false, priority: 'default', tags: 'question', title: 'MDM: ' + info.label + ' nicht pruefbar', message: info.label + ': ' + info.error + '\n\n' + guide } });
    continue;
  }
  if (info.days <= 0) {
    out.push({ json: { item: info.item, expiry: info.expiry, mark: [], ticket: false, priority: 'urgent', tags: 'rotating_light', title: 'MDM: ' + info.label + ' ist ABGELAUFEN', message: info.label + ' ist seit ' + info.expiry + ' abgelaufen. Notfall-Vorgehen siehe Doku (Abschnitt Zertifikat abgelaufen).\n\n' + guide } });
    continue;
  }
  const due = cfg.thresholds.filter((t) => info.days <= t);
  if (due.length === 0 || due.every((t) => sent.includes(t))) continue;
  const smallest = Math.min(...due);
  out.push({ json: {
    item: info.item,
    expiry: info.expiry,
    mark: due,
    ticket: smallest <= 7,
    priority: smallest <= 1 ? 'urgent' : smallest <= 7 ? 'high' : 'default',
    tags: smallest <= 7 ? 'rotating_light' : 'calendar',
    title: 'MDM: ' + info.label + ' laeuft in ' + info.days + ' Tag(en) ab',
    message: info.label + ' laeuft am ' + info.expiry + ' ab (noch ' + info.days + ' Tage).\n\n' + guide
  } });
}
return out;
